<?php
$page_title='Members'; require __DIR__.'/includes/header.php'; $msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{ if(($_POST['action']??'')==='add'){ $stmt=$pdo->prepare('INSERT INTO members(member_code,name,email,phone,address) VALUES(?,?,?,?,?)'); $code='MEM-'.random_int(10000,99999); $stmt->execute([$code,trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['address'])]);$msg='Member added. Code: '.$code; } elseif($_POST['action']==='delete'){ $stmt=$pdo->prepare('DELETE FROM members WHERE id=?');$stmt->execute([(int)$_POST['id']]);$msg='Member deleted.'; } }catch(Throwable $e){$error='Could not save member. Email may already exist or the member has transactions.';}}
$members=$pdo->query("SELECT m.*,COUNT(CASE WHEN t.status='issued' THEN 1 END) issued_count FROM members m LEFT JOIN transactions t ON t.member_id=m.id GROUP BY m.id ORDER BY m.id DESC")->fetchAll();
?><section class="panel"><div class="panel-head"><h2>Library Members</h2><button class="btn primary" onclick="openModal('memberModal')">+ Add Member</button></div><?php if($msg): ?><div class="alert success"><?=e($msg)?></div><?php endif;?><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif;?><div class="table-wrap"><table><thead><tr><th>Member ID</th><th>Name</th><th>Email</th><th>Phone</th><th>Issued</th><th>Action</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><?=e($m['member_code'])?></td><td><?=e($m['name'])?></td><td><?=e($m['email'])?></td><td><?=e($m['phone'])?></td><td><?=$m['issued_count']?></td><td><form method="post" onsubmit="return confirm('Delete this member?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="btn danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></section><div id="memberModal" class="modal"><div class="modal-box"><button class="close" onclick="closeModal('memberModal')">×</button><h2>Add Member</h2><form method="post"><input type="hidden" name="action" value="add"><label>Name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Phone<input name="phone"></label><label>Address<input name="address"></label><button class="btn primary full">Register Member</button></form></div></div><?php require __DIR__.'/includes/footer.php'; ?>
